def apply(inputs, premises):
    question = inputs["current_question"]
    if not premises["nondisclosure_actor_is_receiving_party"]:
        return {"exception_applies": False}
    permitted_classes = premises["permitted_representative_classes"]
    class_match = False
    for recipient_class in permitted_classes:
        if recipient_class in question:
            class_match = True
    if "professional advisors" in question:
        if "legal advisors" in permitted_classes or "financial advisors" in permitted_classes or "accountants" in permitted_classes:
            class_match = True
    exception_applies = class_match and premises["representatives_must_be_confidentiality_bound"] and premises["representatives_must_have_bona_fide_need_to_know"] and premises["disclosure_limited_to_business_purpose"]
    return {"exception_applies": exception_applies}

def apply(inputs, premises):
    question = inputs["current_question"]
    is_disclosure_permission_query = "Receiving Party" in question and "may share some Confidential Information" in question
    if not is_disclosure_permission_query:
        answer = "NotMentioned"
    elif inputs["representative_exception_applies"]:
        answer = "Entailment"
    elif premises["general_third_party_nondisclosure_rule"] and ("third-parties" in question or "third parties" in question):
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}
